static void group(const char *s){groups++;printf("GROUP %s\n",s);}
static void b(uint32_t p,uint8_t v){if(p>=TF_RAM_BASE&&p-TF_RAM_BASE<TF_RAM_SIZE){m.ram[p-TF_RAM_BASE]=v;m.known[p-TF_RAM_BASE]=255;}}
static uint8_t r(uint32_t p){return p>=TF_RAM_BASE&&p-TF_RAM_BASE<TF_RAM_SIZE?m.ram[p-TF_RAM_BASE]:0;}
static void h(uint32_t p,uint16_t v){b(p,(uint8_t)v);b(p+1,(uint8_t)(v>>8));}
static uint16_t rh(uint32_t p){return (uint16_t)(r(p)|((uint16_t)r(p+1)<<8));}
static void w(uint32_t p,uint32_t v){unsigned i;for(i=0;i<4;i++)b(p+i,(uint8_t)(v>>(8*i)));}
static uint32_t rw(uint32_t p){return (uint32_t)r(p)|((uint32_t)r(p+1)<<8)|((uint32_t)r(p+2)<<16)|((uint32_t)r(p+3)<<24);}
static int clock_result(void *ctx,uint32_t token,uint32_t *value){(void)ctx;CHECK(token==0x18f1a||token==0x33cc||token==0x20000986);clock_reads++;if(!clock_known)return 0;*value=sequence_cursor<sequence_size?clock_sequence[sequence_cursor++]:raw_clock;if(mutate_frequency){h(A(0x30ec),mutate_frequency);mutate_frequency=0;}if(mutate_max_enabled){w(A(0x30e8),mutate_max);mutate_max_enabled=0;}return 1;}
static int status_result(void *ctx,rc_adapter *q,unsigned code,uint32_t detail){(void)ctx;(void)detail;CHECK(q==&a);if(status_count<8)status_codes[status_count++]=code;return 1;}
