static void test_source_bytes(void){size_t i;group("literal native bytes and RV32 unsigned branch fields from fixed source");for(i=0;i<sizeof(rc_source_bytes)/sizeof(rc_source_bytes[0]);i++){const rc_source_byte *q=&rc_source_bytes[i];uint32_t word=(uint32_t)q->bytes[0]|((uint32_t)q->bytes[1]<<8)|((uint32_t)q->bytes[2]<<16)|((uint32_t)q->bytes[3]<<24);CHECK(q->n<=4);if(q->image==1){CHECK(q->va>=0x8000&&q->va-0x8000+q->n<=sizeof(runtime));CHECK(memcmp(runtime+q->va-0x8000,q->bytes,q->n)==0);}if(q->opcode){CHECK((word&127u)==q->opcode);CHECK(((word>>12)&7u)==q->funct3);CHECK(((word>>15)&31u)==q->rs1);CHECK(((word>>20)&31u)==q->rs2);}if(q->va==0x19798||q->va==0x3c60){CHECK(q->n==2);CHECK((word&3u)==1&&((word>>13)&7u)==3);CHECK(((word>>7)&31u)==15);CHECK((((word>>2)&31u)<<12)==(q->va==0x19798?0x7000u:0x5000u));}}}
